using namespace std;

int main() {
    int n, m, k;
    cin >> n >> m >> k;
    vector<long long> a(n);  // kept in original order, so position order equals index order
    for (auto &x : a) cin >> x;
    long long ans = 0;
    for (int round = 0; round < m; round++) {
        int len = a.size(), pick = -1;
        auto consider = [&](int i) {
            if (pick < 0 || a[i] > a[pick] || (a[i] == a[pick] && i < pick)) pick = i;
        };
        for (int i = 0; i < min(k, len); i++) consider(i);
        for (int i = max(0, len - k); i < len; i++) consider(i);
        ans += a[pick];
        a.erase(a.begin() + pick);
    }
    cout << ans << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt(), k = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        int len = n;
        long ans = 0;
        for (int round = 0; round < m; round++) {
            int pick = -1;
            for (int i = 0; i < len; i++) {
                if (i >= k && i < len - k) continue;  // only the first k and the last k are candidates
                if (pick < 0 || a[i] > a[pick]) pick = i;
            }
            ans += a[pick];
            System.arraycopy(a, pick + 1, a, pick, len - pick - 1);
            len--;
        }
        System.out.println(ans);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m, k := nextInt(), nextInt(), nextInt()
	a := make([]int, n)
	for i := range a {
		a[i] = nextInt()
	}
	ans := 0
	for round := 0; round < m; round++ {
		pick := -1
		for i := range a {
			if i >= k && i < len(a)-k {
				continue // only the first k and the last k are candidates
			}
			if pick < 0 || a[i] > a[pick] {
				pick = i
			}
		}
		ans += a[pick]
		a = append(a[:pick], a[pick+1:]...)
	}
	fmt.Println(ans)
}
